        // Fund with ETH for constructor transfer
        vm.deal(address(this), 1 ether);

        token = new ProMax{value: 1 ether}(
            tokenName,
            tokenSymbol,
            decimal,
            amountOfTokenWei,
            setMxTxPer,
            setMxWalletPer,
            feeWallet,
            rewardToken,
            minimumTokenBalanceForDividends,
            fee,
            addrs
